const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id);
const choices={method:'bolt',effect:'damage',attribute:'swift',twist:''};
let W=800,H=500,dpr=1,last=0,elapsed=0,player,enemies=[],shots=[],particles=[],rings=[],keys={},stick={x:0,y:0},aim={x:0,y:0},cooldown=0,spawnTimer=0,score=0,wave=1,kills=0,need=6,level=1,xp=0,xpNext=5,gameOver=false,paused=false,toastTimer=0,sound=true,audio;
const waveNames=['The first stirring','Murmurs in the dark','The restless','Hollow-hearted','The last vigil'];
const colors={lime:'#c8f078',pink:'#ed8590',gold:'#e4b66c',cyan:'#83d6cf',purple:'#b99af4'};
function resize(){const r=canvas.getBoundingClientRect();if(!r.width)return;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);W=r.width;H=r.height;ctx.setTransform(dpr,0,0,dpr,0,0);if(player){player.x=Math.min(W-40,Math.max(40,player.x));player.y=Math.min(H-45,Math.max(75,player.y));}}
new ResizeObserver(resize).observe(canvas);
function newRun(){player={x:W*.5,y:H*.58,r:12,hp:100,maxHp:100,invuln:0,faceX:1,faceY:0};enemies=[];shots=[];particles=[];rings=[];score=0;wave=1;kills=0;need=6;level=1;xp=0;xpNext=5;cooldown=0;spawnTimer=.6;gameOver=false;paused=false;choices.method='bolt';choices.effect='damage';choices.attribute='swift';choices.twist='';updateChoices();updateHud();say('A new incantation');}
function config(){let power=18,range=1,speed=1,rate=.42,name='Ember Dart',icon='✦';if(choices.method==='burst'){power=15;range=105;rate=.72;name='Cinder Bloom';icon='✺'}if(choices.method==='beam'){power=24;range=330;rate=.85;name='Starline';icon='⟶'}if(choices.effect==='heal'){power=choices.method==='burst'?20:15;name=choices.method==='burst'?'Mending Halo':'Mend';icon='♡'}if(choices.effect==='force'){power=12;name='Gale '+(choices.method==='beam'?'Lance':'Pulse');icon='✧'}if(choices.attribute==='swift'){speed=.72;rate*=.72}if(choices.attribute==='far'){range*=1.45;speed*=1.12;name='Far '+name}if(choices.attribute==='potent'){power*=1.55;rate*=1.25;name='Greater '+name}if(choices.twist==='blast'){power*=.82;range=choices.method==='burst'?range+28:62;rate*=1.12;name='Volatile '+name}if(choices.twist==='blink'){rate*=1.15;name='Blinking '+name}if(choices.twist==='chain'){power*=.86;name='Chaining '+name}return{power,range,speed,rate,name,icon};}
function updateChoices(){document.querySelectorAll('[data-group]').forEach(group=>{const key=group.dataset.group;group.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',choices[key]===b.dataset.value));});const c=config();$('spellName').textContent=c.name;$('spellIcon').textContent=c.icon;$('spellDesc').textContent=`${choices.method.toUpperCase()} · ${choices.effect.toUpperCase()}${choices.twist?' · '+choices.twist.toUpperCase():''}`;$('impactStat').textContent=Math.round(c.power);$('rangeStat').textContent=choices.method==='beam'?'LONG':choices.method==='burst'?'AREA':choices.attribute==='far'?'LONG':'MEDIUM';$('rateStat').textContent=c.rate<.48?'QUICK':c.rate<.8?'STEADY':'SLOW';$('manaStat').textContent='0';}
document.querySelectorAll('[data-group] button').forEach(b=>b.addEventListener('click',()=>{const group=b.closest('[data-group]').dataset.group;choices[group]=b.dataset.value;updateChoices();playTone(540,.035)}));
function say(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=2;}
function playTone(freq=440,duration=.06){if(!sound)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}catch(e){}}
$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').textContent=sound?'♫':'♪';if(sound)playTone()};
$('castBtn').addEventListener('pointerdown',e=>{e.preventDefault();cast()});
function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture?.(e.pointerId);const p=pointerPos(e);if(gameOver){newRun();return}if(p.y<65&&p.x<W*.22)return;cast(p.x,p.y)});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k===' '&&!e.repeat)cast();if(k==='enter'&&gameOver)newRun()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const pad=$('stick'),knob=$('knob');let padPointer=null;
pad.addEventListener('pointerdown',e=>{e.preventDefault();padPointer=e.pointerId;pad.setPointerCapture(e.pointerId);moveStick(e)});pad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)moveStick(e)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>pad.addEventListener(ev,()=>{padPointer=null;stick.x=stick.y=0;knob.style.transform='translate(0,0)'}));function moveStick(e){const r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=r.width*.34,d=Math.hypot(dx,dy),s=Math.min(1,lim/Math.max(d,1));stick.x=dx*s/lim;stick.y=dy*s/lim;knob.style.transform=`translate(${dx*s}px,${dy*s}px)`}
function cast(tx,ty){if(gameOver||cooldown>0)return;const c=config();cooldown=c.rate;let target;if(tx==null||ty==null){const nearest=enemies.slice().sort((a,b)=>dist(player,a)-dist(player,b))[0];if(nearest){const dx=nearest.x-player.x,dy=nearest.y-player.y,d=Math.hypot(dx,dy)||1;tx=player.x+dx/d*340;ty=player.y+dy/d*340}else{tx=player.x+player.faceX*300;ty=player.y+player.faceY*300}}let dx=tx-player.x,dy=ty-player.y,d=Math.hypot(dx,dy)||1;aim={x:dx/d,y:dy/d};player.faceX=aim.x;player.faceY=aim.y;const type=choices.effect;if(type==='heal'){const amount=c.power;player.hp=Math.min(player.maxHp,player.hp+amount);burst(player.x,player.y,colors.cyan,18);rings.push({x:player.x,y:player.y,r:4,max:60,life:.5,color:colors.cyan});say(`Mended +${amount} vitality`);playTone(620,.12);updateHud();return}
if(choices.method==='burst'){const x=player.x+aim.x*62,y=player.y+aim.y*62;explode(x,y,c.range,c.power,type);if(choices.twist==='blink')blink(x,y);playTone(190,.09);return}
if(choices.method==='beam'){let len=Math.min(d,c.range*(choices.attribute==='far'?1.45:1));const ex=player.x+aim.x*len,ey=player.y+aim.y*len;rings.push({x:player.x,y:player.y,r:0,max:len,life:.18,color:colors.lime,beam:{x:ex,y:ey}});enemies.forEach(m=>{if(pointLine(m.x,m.y,player.x,player.y,ex,ey)<m.r+7&&dist(player,m)<len+4)hitEnemy(m,c.power,type,aim)});if(choices.twist==='blast')explode(ex,ey,54,c.power*.65,type);if(choices.twist==='blink')blink(ex,ey);if(choices.twist==='chain')chainHit(ex,ey,c.power*.55,type,null);playTone(700,.07);return}
shots.push({x:player.x+aim.x*18,y:player.y+aim.y*18,vx:aim.x*(310*c.speed),vy:aim.y*(310*c.speed),life:Math.min(d,c.range*(choices.attribute==='far'?1.45:1))/ (310*c.speed),power:c.power,type,blast:choices.twist==='blast',chain:choices.twist==='chain',blink:choices.twist==='blink',color:type==='force'?colors.cyan:colors.gold,r:5});playTone(520,.045);}
function blink(x,y){const ox=player.x,oy=player.y;player.x=Math.max(25,Math.min(W-25,x));player.y=Math.max(75,Math.min(H-35,y));rings.push({x:ox,y:oy,r:5,max:45,life:.35,color:colors.purple});rings.push({x:player.x,y:player.y,r:5,max:55,life:.4,color:colors.purple});burst(player.x,player.y,colors.purple,12)}
function explode(x,y,r,power,type){rings.push({x,y,r:8,max:r,life:.38,color:type==='force'?colors.cyan:colors.gold});enemies.forEach(m=>{if(dist({x,y},m)<r+m.r)hitEnemy(m,power,type,{x:(m.x-x)/(dist({x,y},m)||1),y:(m.y-y)/(dist({x,y},m)||1)})});burst(x,y,type==='force'?colors.cyan:colors.gold,14);}
function hitEnemy(m,power,type,dir){if(m.dead)return;m.hp-=power;if(type==='force'){m.vx+=(dir?.x||0)*165;m.vy+=(dir?.y||0)*165}m.flash=.12;burst(m.x,m.y,type==='force'?colors.cyan:colors.gold,4);if(m.hp<=0){m.dead=true;score++;kills++;dropXp(m.x,m.y);burst(m.x,m.y,'#a6a895',12);if(choices.twist==='chain')chainHit(m.x,m.y,power*.55,type,m);if(kills>=need)checkWave();updateHud()}}
function chainHit(x,y,power,type,exclude){let target=null,best=145;for(const m of enemies){const d=dist({x,y},m);if(!m.dead&&m!==exclude&&d<best){best=d;target=m}}if(target){rings.push({x,y,r:0,max:best,life:.18,color:colors.purple,beam:{x:target.x,y:target.y}});hitEnemy(target,power,type,{x:(target.x-x)/best,y:(target.y-y)/best})}}
function pointLine(px,py,x1,y1,x2,y2){let dx=x2-x1,dy=y2-y1,t=Math.max(0,Math.min(1,((px-x1)*dx+(py-y1)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(px-(x1+t*dx),py-(y1+t*dy))}
const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function spawn(){const edge=Math.floor(Math.random()*4),pad=32;let x,y;if(edge===0){x=Math.random()*W;y=65}else if(edge===1){x=W-pad;y=70+Math.random()*(H-130)}else if(edge===2){x=Math.random()*W;y=H-35}else{x=pad;y=70+Math.random()*(H-130)}const strong=wave>=3&&Math.random()<.22;enemies.push({x,y,r:strong?15:11,hp:strong?42:25+wave*3,maxHp:strong?42:25+wave*3,speed:strong?25+wave:35+Math.min(wave*2,15),vx:0,vy:0,flash:0,attack:0,dead:false,strong});}
function dropXp(x,y){for(let i=0;i<2;i++)particles.push({x:x+(Math.random()-.5)*12,y:y+(Math.random()-.5)*12,vx:(Math.random()-.5)*35,vy:(Math.random()-.5)*35,life:8,maxLife:8,xp:true,r:4})}
function collectXp(p){xp+=p;while(xp>=xpNext){xp-=xpNext;level++;xpNext+=3;player.maxHp+=8;player.hp=Math.min(player.maxHp,player.hp+24);say(`Level ${level} · vitality restored`);playTone(800,.16)}updateHud()}
function checkWave(){if(kills>=need&&enemies.every(m=>m.dead)){wave++;need=6+wave*2;kills=0;spawnTimer=2.2;player.hp=Math.min(player.maxHp,player.hp+18);say(`Wave ${wave} · the Hollow stirs`);$('waveTitle').textContent=waveNames[Math.min(wave-1,waveNames.length-1)];updateHud()}}
function updateHud(){$('healthText').textContent=`${Math.ceil(player?.hp||100)} / ${player?.maxHp||100}`;$('healthFill').style.width=`${Math.max(0,(player?.hp||0)/(player?.maxHp||100)*100)}%`;$('xpFill').style.width=`${xp/xpNext*100}%`;$('levelText').textContent=`✧  LV ${level}`;$('runState').textContent=`FLOOR ${String(wave).padStart(2,'0')}`}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=20+Math.random()*110;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.3+Math.random()*.42,maxLife:.72,color,r:1+Math.random()*2})}}
function update(dt){if(gameOver)return;elapsed+=dt;cooldown=Math.max(0,cooldown-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}
let mx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+stick.x,my=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+stick.y,mag=Math.hypot(mx,my)||1;if(Math.abs(mx)+Math.abs(my)>.05){mx/=mag;my/=mag;player.faceX=mx;player.faceY=my}player.x=Math.max(22,Math.min(W-22,player.x+mx*177*dt));player.y=Math.max(65,Math.min(H-24,player.y+my*177*dt));player.invuln=Math.max(0,player.invuln-dt);
spawnTimer-=dt;if(spawnTimer<=0&&kills<need&&enemies.filter(m=>!m.dead).length<5+Math.ceil(wave/2)){spawn();spawnTimer=Math.max(.56,1.55-wave*.055)}
for(const m of enemies){if(m.dead)continue;m.flash=Math.max(0,m.flash-dt);m.attack=Math.max(0,m.attack-dt);const dx=player.x-m.x,dy=player.y-m.y,d=Math.hypot(dx,dy)||1;m.vx*=Math.pow(.08,dt);m.vy*=Math.pow(.08,dt);if(d>m.r+player.r+1){m.x+=(dx/d*m.speed+m.vx)*dt;m.y+=(dy/d*m.speed+m.vy)*dt}else if(m.attack<=0&&player.invuln<=0){player.hp-=m.strong?13:8;player.invuln=.55;m.attack=.8;burst(player.x,player.y,colors.pink,8);playTone(110,.08);updateHud();if(player.hp<=0){player.hp=0;gameOver=true;say('Your light fades… tap to begin again');}}}
for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;let hit=false;for(const m of enemies){if(!m.dead&&dist(s,m)<m.r+s.r){hitEnemy(m,s.power,s.type,{x:s.vx/Math.hypot(s.vx,s.vy),y:s.vy/Math.hypot(s.vx,s.vy)});if(s.blast)explode(s.x,s.y,58,s.power*.72,s.type);if(s.chain)chainHit(s.x,s.y,s.power*.6,s.type,m);if(s.blink)blink(s.x,s.y);hit=true;break}}if(hit||s.life<=0||s.x<0||s.y<0||s.x>W||s.y>H){if(!hit&&s.blast)explode(s.x,s.y,58,s.power*.65,s.type);if(!hit&&s.blink)blink(s.x,s.y);shots.splice(i,1)}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];if(p.xp){const d=dist(p,player);if(d<115){p.vx+=(player.x-p.x)*3*dt;p.vy+=(player.y-p.y)*3*dt}if(d<player.r+8){particles.splice(i,1);collectXp(1);playTone(760,.025);continue}}p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.3,dt);p.vy*=Math.pow(.3,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}for(let i=rings.length-1;i>=0;i--){rings[i].life-=dt;if(rings[i].life<=0)rings.splice(i,1)}enemies=enemies.filter(m=>!m.dead||elapsed-m.deathTime<0);}

